import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
geom = ee.Geometry.Polygon([[
  [-118.45, 33.65],
  [-118.45, 34.05],
  [-118.00, 34.05],
  [-118.00, 33.65],
]])
band = 'tropospheric_NO2_column_number_density'
scale = 3000

def try_col(ic_id, start, end, g):
    return ee.ImageCollection(ic_id).filterDate(start, end).filterBounds(g)

def get_collection(start, end, g):
    # Primary window: OFFL -> NRTI
    col_offl = try_col('COPERNICUS/S5P/OFFL/L3_NO2', start, end, g)
    n_offl = col_offl.size().getInfo()
    if n_offl and n_offl > 0:
        return col_offl, 'OFFL', False, n_offl
    col_nrti = try_col('COPERNICUS/S5P/NRTI/L3_NO2', start, end, g)
    n_nrti = col_nrti.size().getInfo()
    if n_nrti and n_nrti > 0:
        return col_nrti, 'NRTI', False, n_nrti
    # Widen ±2 days
    start2 = ee.Date(start).advance(-2, 'day')
    end2 = ee.Date(end).advance(2, 'day')
    col_offl2 = try_col('COPERNICUS/S5P/OFFL/L3_NO2', start2, end2, g)
    n_offl2 = col_offl2.size().getInfo()
    if n_offl2 and n_offl2 > 0:
        return col_offl2, 'OFFL', True, n_offl2
    col_nrti2 = try_col('COPERNICUS/S5P/NRTI/L3_NO2', start2, end2, g)
    n_nrti2 = col_nrti2.size().getInfo()
    if n_nrti2 and n_nrti2 > 0:
        return col_nrti2, 'NRTI', True, n_nrti2
    return None, None, False, 0

def qa_mask(img):
    return img.updateMask(img.select('qa_value').gte(0.75))

def compute_stats(year):
    start = ee.Date.fromYMD(year, 10, 1)
    end = ee.Date.fromYMD(year, 10, 24)  # end-exclusive
    col, source, expanded, n_images = get_collection(start, end, geom)
    if col is None:
        return {'status': 'C1', 'year': year}
    # Keep only needed bands to avoid schema mismatches
    col = col.select([band, 'qa_value'])
    masked = col.map(qa_mask)
    mean_img = masked.mean()

    # Valid pixel count after masking
    valid = mean_img.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom, scale=scale, maxPixels=1e9
    ).get(band).getInfo()
    if valid is None:
        valid = 0
    # Total pixel count at same scale
    total = ee.Image(1).rename('const').reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom, scale=scale, maxPixels=1e9
    ).get('const').getInfo()
    if total is None or total == 0:
        return {'status': 'C3', 'year': year}

    if valid == 0:
        return {'status': 'C2', 'year': year, 'source': source, 'expanded': expanded,
                'n_images': n_images, 'valid': valid, 'total': total, 'mean': None}

    mean_val = mean_img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom, scale=scale, maxPixels=1e9
    ).get(band).getInfo()

    if mean_val is None or (isinstance(mean_val, float) and not math.isfinite(mean_val)):
        return {'status': 'C3', 'year': year}

    return {'status': 'OK', 'year': year, 'source': source, 'expanded': expanded,
            'n_images': n_images, 'valid': int(valid), 'total': int(total),
            'mean': float(mean_val)}

try:
    years = [2018, 2019, 2021]
    results = {y: compute_stats(y) for y in years}

    # Early exits for collection/pixel/calculation issues
    for y in years:
        r = results[y]
        if r['status'] == 'C1':
            print(f"{y}: Images=0")
            print("C1")
            raise SystemExit
        if r['status'] == 'C2':
            src = r.get('source', 'NA'); exp = '*' if r.get('expanded', False) else ''
            print(f"{y} {src}{exp}: Images={r.get('n_images',0)}, ValidPix={r['valid']}/{r['total']} (0.0%), Mean=None")
            print("C2")
            raise SystemExit
        if r['status'] == 'C3':
            print(f"{y}: Calculation failure.")
            print("C3")
            raise SystemExit

    # Concise evidence lines (<=20 total)
    for y in [2018, 2019, 2021]:
        r = results[y]
        vpct = 100.0 * r['valid'] / r['total'] if r['total'] else 0.0
        src = r['source']; exp = '*' if r['expanded'] else ''
        print(f"{y} {src}{exp}: Images={r['n_images']}, ValidPix={r['valid']}/{r['total']} ({vpct:.1f}%), Mean={r['mean']:.2e} mol/m^2")

    m18 = results[2018]['mean']; m19 = results[2019]['mean']; m21 = results[2021]['mean']
    if any(v is None or not math.isfinite(v) for v in [m18, m19, m21]):
        print("C3")
    elif (m21 < m19) and (m21 < m18):
        print("A")
    else:
        print("B")

except Exception:
    print("D")
